fn ElementInList(list: List[Int], value: Int) -> Bool
  requires len(list) >= 0
  ensures result == contains(list, value)
  effects pure
  example ElementInList([1, 2, 3], 2) == true
  example ElementInList([1, 2, 3], 4) == false
  example ElementInList([], 1) == false
{
  match list {
    [] => false
    [h, ..t] => if h == value then true else ElementInList(t, value)
  }
}

fn AnyValueExists(seq1: List[Int], seq2: List[Int]) -> Bool
  requires (len(seq1) >= 0)
  ensures (result == (exists i in 0..len(seq1): contains(seq2, seq1[i])))
  effects pure
  example AnyValueExists([1, 2], [2, 3]) == true
  example AnyValueExists([1, 2], [3, 4]) == false
  example AnyValueExists([], [1, 2]) == false
{
  match seq1 {
    [] => false
    [h, ..t] => if ElementInList(seq2, h) then true else AnyValueExists(t, seq2)
  }
}

